import { useEffect, useMemo, useState } from "react";

export default function Reviews() {
  const [reviews, setReviews] = useState([]);
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const [editingId, setEditingId] = useState(null);
  const [editMessage, setEditMessage] = useState("");
  const [editRating, setEditRating] = useState(5);

  /* ================= FETCH REVIEWS ================= */
  const fetchReviews = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      if (!token) {
        setError("Admin not authenticated");
        return;
      }

      const res = await fetch("http://localhost:5001/admin/reviews", {
        headers: { Authorization: "Bearer " + token },
      });

      if (!res.ok) throw new Error("Fetch failed");

      const data = await res.json();
      setReviews(
        Array.isArray(data)
          ? data.sort(
              (a, b) =>
                new Date(b.created_at) - new Date(a.created_at)
            )
          : []
      );
    } catch (err) {
      console.error(err);
      setError("Failed to load reviews");
    }
  };

  /* ================= FETCH ANALYTICS ================= */
  const fetchAnalytics = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      if (!token) return;

      const res = await fetch(
        "http://localhost:5001/admin/reviews/analytics",
        { headers: { Authorization: "Bearer " + token } }
      );

      if (!res.ok) throw new Error("Analytics failed");
      const data = await res.json();
      setAnalytics(data);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    Promise.all([fetchReviews(), fetchAnalytics()]).finally(
      () => setLoading(false)
    );
  }, []);

  /* ================= UPDATE STATUS ================= */
  const updateStatus = async (id, status) => {
    try {
      const token = localStorage.getItem("adminToken");
      if (!token) return;

      const res = await fetch(
        `http://localhost:5001/admin/reviews/${id}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: "Bearer " + token,
          },
          body: JSON.stringify({ status }),
        }
      );

      if (!res.ok) throw new Error("Update failed");

      setReviews((prev) =>
        prev.map((r) => (r.id === id ? { ...r, status } : r))
      );
      fetchAnalytics();
    } catch (err) {
      console.error(err);
    }
  };

  /* ================= EDIT ================= */
  const startEdit = (r) => {
    setEditingId(r.id);
    setEditMessage(r.message);
    setEditRating(r.rating);
  };

  const saveUpdate = async (id) => {
    try {
      const token = localStorage.getItem("adminToken");
      if (!token) return;

      const res = await fetch(
        `http://localhost:5001/admin/reviews/${id}`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: "Bearer " + token,
          },
          body: JSON.stringify({
            message: editMessage,
            rating: editRating,
          }),
        }
      );

      if (!res.ok) throw new Error("Save failed");

      setReviews((prev) =>
        prev.map((r) =>
          r.id === id
            ? { ...r, message: editMessage, rating: editRating }
            : r
        )
      );
      setEditingId(null);
      fetchAnalytics();
    } catch (err) {
      console.error(err);
    }
  };

  /* ================= PRIORITY SORT ================= */
  const sortedReviews = useMemo(() => {
    const priority = { Flagged: 0, Hidden: 1, Active: 2 };
    return [...reviews].sort(
      (a, b) => priority[a.status] - priority[b.status]
    );
  }, [reviews]);

  /* ================= UI ================= */
  return (
    <div className="p-10 text-white">
      <h1 className="text-4xl font-bold text-yellow-400 mb-10">
        Reviews Intelligence Dashboard
      </h1>

      {/* ================= ANALYTICS ================= */}
      {analytics && (
        <div className="grid md:grid-cols-4 gap-6 mb-14">
          {[
            {
              label: "Avg Rating",
              value: analytics.avgRating?.toFixed(1) + " ★",
            },
            {
              label: "Active Reviews",
              value: analytics.activeReviews,
            },
            {
              label: "Flagged Reviews",
              value: analytics.flaggedReviews,
            },
            {
              label: "NPS Score",
              value: analytics.nps + "%",
            },
          ].map((c, i) => (
            <div
              key={i}
              className="bg-gradient-to-br from-[#0b0b0b] to-[#111]
                         border border-yellow-500/30 rounded-3xl
                         p-8 shadow-xl text-center"
            >
              <p className="text-gray-400 text-sm tracking-wide">
                {c.label}
              </p>
              <p className="text-yellow-400 text-4xl font-bold mt-4">
                {c.value}
              </p>
            </div>
          ))}
        </div>
      )}

      {/* ================= REVIEWS ================= */}
      <h2 className="text-2xl font-semibold text-yellow-400 mb-6">
        Moderation Queue
      </h2>

      {loading ? (
        <p className="text-gray-400">Loading reviews…</p>
      ) : error ? (
        <p className="text-red-400">{error}</p>
      ) : sortedReviews.length === 0 ? (
        <p className="text-gray-500">No reviews found</p>
      ) : (
        <div className="space-y-6 max-w-6xl">
          {sortedReviews.map((review) => (
            <div
              key={review.id}
              className="bg-gradient-to-br from-[#0b0b0b] to-[#111]
                         border border-yellow-500/30 rounded-2xl
                         p-6 shadow-xl"
            >
              {/* HEADER */}
              <div className="flex justify-between items-center mb-3">
                <h2 className="text-lg font-semibold text-yellow-400">
                  {review.name}
                </h2>

                <span
                  className={`text-xs px-3 py-1 rounded-full font-semibold ${
                    review.status === "Active"
                      ? "bg-green-500/20 text-green-400"
                      : review.status === "Flagged"
                      ? "bg-orange-500/20 text-orange-400"
                      : "bg-red-500/20 text-red-400"
                  }`}
                >
                  {review.status}
                </span>
              </div>

              {/* EDIT MODE */}
              {editingId === review.id ? (
                <>
                  <select
                    value={editRating}
                    onChange={(e) =>
                      setEditRating(Number(e.target.value))
                    }
                    className="mb-3 bg-black border border-yellow-500 rounded px-3 py-1"
                  >
                    {[1, 2, 3, 4, 5].map((n) => (
                      <option key={n} value={n}>
                        {n} Star
                      </option>
                    ))}
                  </select>

                  <textarea
                    value={editMessage}
                    onChange={(e) =>
                      setEditMessage(e.target.value)
                    }
                    className="w-full bg-black border border-yellow-500 rounded p-3 mb-3"
                    rows={3}
                  />

                  <div className="flex gap-3">
                    <button
                      onClick={() => saveUpdate(review.id)}
                      className="bg-yellow-400 text-black px-4 py-1 rounded-lg font-semibold"
                    >
                      Save
                    </button>
                    <button
                      onClick={() => setEditingId(null)}
                      className="bg-gray-600 px-4 py-1 rounded-lg"
                    >
                      Cancel
                    </button>
                  </div>
                </>
              ) : (
                <>
                  {/* RATING */}
                  <div className="flex mb-3">
                    {[1, 2, 3, 4, 5].map((n) => (
                      <span
                        key={n}
                        className={
                          n <= review.rating
                            ? "text-yellow-400"
                            : "text-gray-600"
                        }
                      >
                        ★
                      </span>
                    ))}
                  </div>

                  <p className="text-gray-300 mb-4">
                    {review.message}
                  </p>

                  <p className="text-xs text-gray-500 mb-4">
                    {new Date(
                      review.created_at
                    ).toLocaleString()}
                  </p>

                  <div className="flex gap-3 flex-wrap">
                    <button
                      onClick={() => startEdit(review)}
                      className="bg-blue-500 text-black px-4 py-1 rounded-lg font-semibold"
                    >
                      Edit
                    </button>

                    {review.status !== "Active" && (
                      <button
                        onClick={() =>
                          updateStatus(review.id, "Active")
                        }
                        className="bg-green-500 text-black px-4 py-1 rounded-lg font-semibold"
                      >
                        Publish
                      </button>
                    )}

                    {review.status !== "Hidden" && (
                      <button
                        onClick={() =>
                          updateStatus(review.id, "Hidden")
                        }
                        className="bg-red-500 text-black px-4 py-1 rounded-lg font-semibold"
                      >
                        Hide
                      </button>
                    )}
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
